#[test]
fn from_str_base_unit() {
    let abbr = PowerUnit::Watt.abbreviation();
    let s = format!("1 {}", abbr);
    let parsed: Power = s.parse().expect("parse failed");
    let expected = Power::from_watts(1.0).as_base();
    assert!((parsed.as_base() - expected).abs() / expected.abs().max(1.0) < RT_EPS);
}
